pub(crate) fn new_cmd<S: AsRef<std::ffi::OsStr>>(program: S) -> Command {
    let mut c = std::process::Command::new(program);
    #[cfg(windows)]
    c.creation_flags(0x08000000);
    c
}

fn minecraft_dir() -> PathBuf {
    let appdata = std::env::var("APPDATA").unwrap_or_else(|_| ".".to_string());
    PathBuf::from(appdata).join(".minecraft")
}

fn profiles_path() -> PathBuf {
    minecraft_dir().join("obsidia").join("profiles.json")
}

#[derive(Serialize, Deserialize, Clone)]
pub struct Profile {
    pub name: String,
    pub version: String,
    pub username: String,
    pub ram: String,
    pub java_path: Option<String>,
    /// "Vanilla", "Fabric" o "Forge". Los perfiles viejos no lo traen: queda en None.
    #[serde(default)]
    pub loader: Option<String>,
    #[serde(default)]
    pub loader_version: Option<String>,
    #[serde(default)]
    pub fullscreen: bool,
    /// Identificador de la instancia (carpeta propia con mods, packs, config y mundos).
    /// Los perfiles viejos no lo traen y siguen usando `.minecraft` tal cual.
    #[serde(default)]
    pub id: Option<String>,
    /// Bloque elegido para representar el perfil en la UI (opcional).
    #[serde(default)]
    pub block: Option<String>,
}

/// Carpeta de juego de una instancia. Sin id (perfiles viejos) es `.minecraft`; con id es
/// `.minecraft/obsidia/instances/<id>`. `libraries`, `assets`, `versions` y `runtime` siguen
/// compartidos en `.minecraft` para no bajar lo mismo varias veces.
fn migrate_one_file(src: &Path, dst: &Path) -> Result<(), String> {
    if !dst.exists() {
        if let Some(parent) = dst.parent() { fs::create_dir_all(parent).map_err(|e| e.to_string())?; }
        fs::rename(src, dst).or_else(|_| fs::copy(src, dst).map(|_| ()).and_then(|_| fs::remove_file(src)).map_err(|e| e.to_string()))?;
        return Ok(());
    }
    // Conflicto: conservar ambos con sufijo.
    let stem = dst.file_stem().and_then(|s| s.to_str()).unwrap_or("file");
    let ext = dst.extension().and_then(|e| e.to_str()).unwrap_or("");
    for i in 1..=1000 {
        let name = if ext.is_empty() { format!("{} ({})", stem, i) } else { format!("{} ({}).{}", stem, i, ext) };
        let alt = dst.with_file_name(name);
        if !alt.exists() {
            if let Some(parent) = alt.parent() { fs::create_dir_all(parent).map_err(|e| e.to_string())?; }
            fs::rename(src, &alt).or_else(|_| fs::copy(src, &alt).map(|_| ()).and_then(|_| fs::remove_file(src)).map_err(|e| e.to_string()))?;
            return Ok(());
        }
    }
    Err("demasiados conflictos de nombre".to_string())
}

fn migrate_dir_recursive(src: &Path, dst: &Path) -> Result<(), String> {
    fs::create_dir_all(dst).map_err(|e| e.to_string())?;
    for entry in fs::read_dir(src).map_err(|e| e.to_string())? {
        let entry = entry.map_err(|e| e.to_string())?;
        let from = entry.path();
        let to = dst.join(entry.file_name());
        if from.is_dir() {
            migrate_dir_recursive(&from, &to)?;
        } else {
            migrate_one_file(&from, &to)?;
        }
    }
    Ok(())
}

fn migrate_instances() {
    let old_root = minecraft_dir().join("obsidia").join("instances");
    let new_root = minecraft_dir().join("instances");
    if !old_root.exists() { return; }
    let _ = fs::create_dir_all(&new_root);
    if let Ok(entries) = fs::read_dir(&old_root) {
        for e in entries.flatten() {
            let src = e.path();
            if !src.is_dir() { continue; }
            let name = e.file_name();
            let dst = new_root.join(&name);
            if migrate_dir_recursive(&src, &dst).is_ok() {
                // VerificaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n bÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡sica: borrar origen solo si quedÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³ vacÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â­o.
                let _ = fs::remove_dir_all(&src);
            }
        }
    }
    // Borrar raÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â­z vieja si quedÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³ vacÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â­a.
    let _ = fs::remove_dir(&old_root);
}

