#[derive(Serialize)]
pub struct JavaInfo {
    pub path: String,
    pub version: String,
}

#[tauri::command]
fn get_installed_versions() -> Result<Vec<String>, String> {
    let dir = minecraft_dir().join("versions");
    let mut out = Vec::new();
    if let Ok(entries) = fs::read_dir(&dir) {
        for entry in entries.flatten() {
            if entry.path().is_dir()
                && let Some(name) = entry.file_name().to_str() {
                    out.push(name.to_string());
                }
        }
    }
    out.sort();
    Ok(out)
}

#[tauri::command]
async fn list_versions() -> Result<Vec<String>, String> {
    let resp = reqwest::get("https://piston-meta.mojang.com/mc/game/version_manifest_v2.json")
        .await
        .map_err(|e| e.to_string())?;
    let json: serde_json::Value = resp.json().await.map_err(|e| e.to_string())?;
    let mut ids = Vec::new();
    if let Some(versions) = json.get("versions").and_then(|v| v.as_array()) {
        for v in versions {
            if v.get("type").and_then(|t| t.as_str()) == Some("release")
                && let Some(id) = v.get("id").and_then(|i| i.as_str()) {
                    ids.push(id.to_string());
                    if ids.len() >= 60 {
                        break;
                    }
                }
        }
    }
    Ok(ids)
}
#[tauri::command]
async fn list_fabric_versions(mc_version: String) -> Result<Vec<String>, String> {
    let url = format!("https://meta.fabricmc.net/v2/versions/loader/{}", mc_version);
    let resp = reqwest::get(&url).await.map_err(|e| e.to_string())?;
    if !resp.status().is_success() {
        return Err(format!("fabric versions request failed: HTTP {}", resp.status()));
    }
    let json: serde_json::Value = resp.json().await.map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    if let Some(arr) = json.as_array() {
        for e in arr {
            if let Some(v) = e.get("loader").and_then(|l| l.get("version")).and_then(|v| v.as_str()) {
                out.push(v.to_string());
            }
        }
    }
    Ok(out)
}

#[tauri::command]
async fn list_forge_versions(mc_version: String) -> Result<Vec<String>, String> {
    let resp = reqwest::get("https://maven.minecraftforge.net/net/minecraftforge/forge/maven-metadata.xml")
        .await.map_err(|e| e.to_string())?;
    if !resp.status().is_success() {
        return Err(format!("forge versions request failed: HTTP {}", resp.status()));
    }
    let text = resp.text().await.map_err(|e| e.to_string())?;
    let prefix = format!("{}-", mc_version);
    let mut out = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if !line.starts_with("<version>") || !line.ends_with("</version>") { continue; }
        let v = &line["<version>".len()..line.len()-"</version>".len()];
        if let Some(rest) = v.strip_prefix(&prefix) {
            out.push(rest.to_string());
        }
    }
    out.sort();
    out.dedup();
    Ok(out)
}

