#[allow(clippy::too_many_arguments)]
#[tauri::command]
async fn launch_version(
    app: tauri::AppHandle,
    version: String,
    username: String,
    ram: Option<String>,
    java_path: Option<String>,
    server: Option<String>,
    fullscreen: Option<bool>,
    instance: Option<String>,
) -> Result<String, String> {
    let gd = game_dir(instance.as_deref())?;
    let player = match auth::player().await? {
        Some(p) => p,
        None => launcher::offline_player(&username)?,
    };
    let mc = minecraft_dir();
    let opts = launcher::LaunchOptions {
        ram,
        java_path,
        server,
        fullscreen: fullscreen.unwrap_or(false),
    };
    tauri::async_runtime::spawn_blocking(move || launcher::launch(&app, &mc, &gd, &version, player, opts, fallback_java))
    .await
    .map_err(|e| e.to_string())?
}

fn sha1_hex(bytes: &[u8]) -> String {
    let mut h = Sha1::new();
    h.update(bytes);
    format!("{:x}", h.finalize())
}

